        assertNotNull(c.comments);
        assertEquals(comments, c.comments);
    }

    @Test
    public void setCommentShouldOverwriteExistingComments() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration c = new CommentsConfiguration(comments);
        c.setComment("path1", "line1");
        assertEquals(1, c.comments.get("path1").size());
    }

    @Test
    public void setCommentShouldAddNewLinesAsEmptyLines() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration c = new CommentsConfiguration(comments);
        String commentLines[] = {"line1", "\n", "line2"};
        c.setComment("path1", commentLines);
        assertEquals(3, c.comments.get("path1").size());
    }

    @Test
    public void setCommentShouldRegisterCommentForProvidedPath() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration c = new CommentsConfiguration(comments);
        String commentLines[] = {"line1", "\n", "line2"};
        c.setComment("path1", commentLines);
        assertNotNull(c.comments.get("path1"));
    }

    @Test
    public void setCommentShouldNotRegisterMultipleTimesForSamePath() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration c = new CommentsConfiguration(comments);
        String commentLines[] = {"line1", "\n", "line2"};
        c.setComment("path1", commentLines);
        assertEquals(1, c.comments.get("path1").size());
    }

    @Test
    public void getAllCommentsShouldReturnUnmodifiableMap() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration c = new CommentsConfiguration(comments);
        Map<String, @UnmodifiableView List<String>> result = c.getAllComments();
        assertTrue(result instanceof java.util.Map);
        assertFalse(java.util.Collections.unmodifiableMap(result).isMutable());
    }

    @Test
    public void getAllCommentsShouldReturnMapWithAllComments() {
        Map<String, List<String>> comments = new HashMap<>();
        String commentLines[] = {"line1", "\n", "line2"};
        CommentsConfiguration c = new CommentsConfiguration(comments);
        c.setComment("path1", commentLines);
        assertEquals(1, c.comments.get("path1").size());
        Map<String, @UnmodifiableView List<String>> result = c.getAllComments();
        assertNotNull(result);
        assertTrue(result.containsKey("path1"));
    }

    @Test
    public void getAllCommentsShouldReturnEmptyMapWhenNoComments() {
        CommentsConfiguration c = new CommentsConfiguration(new HashMap<>());
        assertEquals(0, ((java.util.Map) c.getAllComments()).size());
    }
